CREATE POLICY plan_cores_fora_linha_read ON public.map_config AS PERMISSIVE FOR SELECT TO authenticated USING (key = 'plan_cores_fora_de_linha' AND (public.has_role(auth.uid(), 'gestor'::public.app_role) OR public.has_area(auth.uid(), 'plan')));
CREATE POLICY plan_cores_fora_linha_insert_admin ON public.map_config AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (key <> 'plan_cores_fora_de_linha' OR public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY plan_cores_fora_linha_update_admin ON public.map_config AS RESTRICTIVE FOR UPDATE TO authenticated USING (key <> 'plan_cores_fora_de_linha' OR public.has_role(auth.uid(), 'admin'::public.app_role)) WITH CHECK (key <> 'plan_cores_fora_de_linha' OR public.has_role(auth.uid(), 'admin'::public.app_role));
CREATE POLICY plan_cores_fora_linha_delete_admin ON public.map_config AS RESTRICTIVE FOR DELETE TO authenticated USING (key <> 'plan_cores_fora_de_linha' OR public.has_role(auth.uid(), 'admin'::public.app_role));